use crate::*;
use crate::owned::tree::{NativeValueSource,NativeTreeKind};
use crate::owned::{NativeRecordSchema,NativeSchemaLeaf};
use crate::owned::tree::variant::*;
use crate::{DslValue,retained_clone::RetainedCloneSource};
fn all(i:usize)->Option<NativeRecordSchema>{["empty","tuple","record"].get(i).map(|name|NativeRecordSchema::Leaf(NativeSchemaLeaf{name,ordinal:i as u32}))}
fn units(i:usize)->Option<NativeRecordSchema>{if i==0{all(i)}else if i<3{Some(NativeRecordSchema::Skip)}else{None}}
fn data(i:usize)->Option<NativeRecordSchema>{if i==0{Some(NativeRecordSchema::Skip)}else{all(i)}}
fn tag(i:usize)->Option<NativeRecordSchema>{(i==0).then_some(NativeRecordSchema::Leaf(NativeSchemaLeaf{name:"kind",ordinal:0}))}
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
#[test]fn actual_native_variant_selection_preserves_wire_case_and_cancelled_original_ownership(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];for case in law["cases"].as_array().unwrap(){for cut in std::iter::once(None).chain(law["cancelCuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()))){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let maximum=s["maximumTurns"].as_u64().unwrap();let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(DslValue::from(case["input"].clone()),&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w,p,work,_,_|post(w.0,w.1,p,work))};let spec=NativeVariantSpec{all,units,data,count:3,tag:case["tagged"].as_bool().unwrap().then_some(tag as fn(usize)->Option<NativeRecordSchema>)};let(mut cursor,heap)=crate::observe_retirement_allocations(||NativeVariantSelector::new(spec));assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);for _ in 0..cut.unwrap_or(maximum){if cursor.result().is_some(){break}let d=cursor.demands(source.borrow(),4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,..bank};for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(turn.result.unwrap().progress(),Default::default());}let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(source.borrow(),&mut control,4096,g));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}if cut.is_none(){let result=cursor.result().unwrap();assert!(!result.direct);assert_eq!(serde_json::json!(result.index),case["selected"]);assert_eq!(serde_json::Value::from(source.borrow().get()),case["input"]);}cursor.begin_close();for _ in 0..maximum{if cursor.terminal_is_empty(){break}let(turn,heap)=crate::observe_retirement_allocations(||cursor.close_step(RetainedCloneGrant{maximum_items:1,..bank}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}assert!(cursor.terminal_is_empty());drop(cursor);for _ in 0..maximum{if source.terminal_is_empty(){break}let(turn,heap)=crate::observe_retirement_allocations(||source.close_step(RetainedCloneGrant{maximum_items:1,..bank}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);}assert!(source.terminal_is_empty());}}}
